package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsDataFramework {
 @GameTest(template="empty") public static void fullPrivateFoodStorageCanExchangeWithoutMintOrOverflow(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var t=CityTrade.get(f.server);var town=new CityTrade.Town();town.city=f.city.id;t.state.towns.put(town.city,town);var family=d.state.families.get(f.person.family);var first=f.box();NpcStorage.box(first).stock.wheat=10;for(int n=1;n<3;n++){var box=new RuralSettlement.Box();box.city=f.city.id;box.pos=f.chest.above(n).asLong();box.linked=true;box.stock.family=family.id;box.stock.wheat=10;d.state.boxes.put(RuralSettlement.key(box.city,box.pos),box);}var headId=UUID.randomUUID();f.city.residents.add(headId);CityEconomy.get(f.server).state.accounts.put(CityEconomy.person(headId),20L);var head=d.enroll(f.server,f.city,headId,"换货头人");head.role=RuralRules.Role.MERCHANT;var source=new RuralSettlement.Box();source.city=f.city.id;source.pos=f.city.bounds.min().asLong();source.linked=true;source.stock.family=head.family;source.stock.cooked[0]=1;d.state.boxes.put(RuralSettlement.key(source.city,source.pos),source);var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=f.city.id;b.kind="head";b.owner=b.worker=headId;b.account=CityEconomy.person(headId);t.state.businesses.put(b.id,b);long cash=f.money();long swaps=t.state.run.foodBarterWheat;int paid=t.improvementTrade(f.server,f.person,family,b,0,true,18);h.assertTrue(paid==14&&f.money()==cash,"18-silver meat less one4-silver wheat moves14 existing silver");h.assertTrue(RuralRules.count(d.stocks(family.id),false)==29&&source.stock.wheat==1&&source.stock.cooked[0]==0&&RuralMeat.count(d.stocks(family.id),true,0)==1&&RuralRules.capacity(d.stocks(family.id))==0,"Atomic swap preserves all31 food units and ten-per-box cap");h.assertTrue(t.state.run.foodBarterWheat==swaps+1,"Bartered grain is explicit, not new harvest");source.stock.cooked[0]=1;int before=RuralRules.count(d.stocks(family.id),false);h.assertTrue(t.improvementTrade(f.server,f.person,family,b,0,true,999)==-1&&f.money()==cash&&RuralRules.count(d.stocks(family.id),false)==before,"Failed payment cannot remove either party's food");t.state.businesses.remove(b.id);t.state.towns.remove(town.city);}h.succeed();}
 @GameTest(template="empty") public static void unpaidEmployeeCanLeaveWithoutStealingBusinessCapital(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var t=CityTrade.get(f.server);var town=new CityTrade.Town();town.city=f.city.id;town.urban=true;t.state.towns.put(town.city,town);var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=f.city.id;b.kind="supplier_helper";b.site=f.bench.asLong();var point=RuralSettlement.get(f.server).state.sites.values().stream().filter(v->f.worker.equals(v.worker)).findFirst().orElseThrow();point.kind="supplier";point.expectedBlock="minecraft:crafting_table";b.worker=b.owner=f.worker;b.account="trade:"+b.id;t.state.businesses.put(b.id,b);f.person.role=RuralRules.Role.SUPPLIER;CityEconomy.get(f.server).state.accounts.put(CityEconomy.person(f.worker),0L);t.state.staffIncomeAt.put(f.worker,0L);long cash=f.money();FamilyLivelihood.unpaid(f.server,f.city,f.person,120000);h.assertTrue(f.person.role==RuralRules.Role.NONE&&f.money()==cash&&!f.person.dead,"No wages for5 days and food risk releases employee, preserving money and identity");h.assertTrue(!FamilyLivelihood.seek(f.server,f.city,f.person),"Cannot immediately re-enter an unviable unpaid supplier job");t.state.staffIncomeAt.remove(f.worker);t.state.businesses.remove(b.id);t.state.towns.remove(town.city);}h.succeed();}
 @GameTest(template="empty") public static void existingStaplesDoNotNeedASecondEmptyMealSpace(GameTestHelper h){h.assertTrue(DataCityRules.improvementRoom(26,4,4),"Two-person farm with26 staples and4 free slots may buy one meat, no duplicate reserve");h.assertTrue(!DataCityRules.improvementRoom(30,0,4),"Truly full storage still blocks buying");h.assertTrue(!DataCityRules.improvementRoom(4,10,4),"Insufficient staple reserve still blocks optional food");h.succeed();}
 @GameTest(template="empty") public static void foodProtectionUsesActualFiniteQuote(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var t=CityTrade.get(f.server);var town=new CityTrade.Town();town.city=f.city.id;town.urban=true;t.state.towns.put(town.city,town);h.assertTrue(CityWorksFinance.protectedFood(f.server,f.worker)==64,"Without a household processor, reserve four ready portions at actual bread shortage quote16, not an imaginary raw-grain meal");t.state.towns.remove(town.city);}h.succeed();}
 @GameTest(template="empty") public static void templateCannotSmuggleInitialSavings(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var in=new CityDataTemplate.Template();in.min=new int[]{250000,90,250000};in.max=new int[]{250010,95,250010};in.source=f.city.id;in.budget=20;in.personalSilver=50;in.residents.add("测试居民");long before=f.money();int n=CityData.get(f.server).cities.size();boolean rejected=false;try{CityDataTemplate.create(f.server,f.worker,in);}catch(IllegalArgumentException ex){rejected=true;}h.assertTrue(rejected&&f.money()==before&&CityData.get(f.server).cities.size()==n,"Personal seed funds cannot exceed the actual transferred budget");}h.succeed();}
 @GameTest(template="empty") public static void localJobSearchUsesVacancyWithoutNewAssets(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var id=UUID.randomUUID();f.city.residents.add(id);CityEconomy.get(f.server).state.accounts.put(CityEconomy.person(id),0L);var p=d.enroll(f.server,f.city,id,"本地求职者");var oldSite=d.state.sites.values().stream().filter(v->f.worker.equals(v.worker)).findFirst().orElseThrow();f.person.dead=true;long cash=f.money();int n=d.state.people.size();boolean employed=FamilyLivelihood.seek(f.server,f.city,p);h.assertTrue(employed&&p.role==RuralRules.Role.ARTISAN&&oldSite.worker.equals(id)&&f.money()==cash&&d.state.people.size()==n,"Existing healthy resident fills a real vacancy, no actor or cash grant");}h.succeed();}
 @GameTest(template="empty") public static void constructionSupplyCannotCreateFood(GameTestHelper h){var st=new CityHousing.State();st.testSupply=true;st.constructionSupplyOnly=true;CityHousing.seedCatalog(st);st.market.put("minecraft:bread",new CityHousing.Material());CityHousing.advanceSupply(st,1200);h.assertTrue(st.market.get("minecraft:bread").stock==0&&st.market.get("minecraft:oak_planks").stock>0,"Construction fixtures never refill staple food");h.succeed();}
 @GameTest(template="empty") public static void virtualFoundationCanBuildBeforeItsWorkBenchExists(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){f.city.works.virtual=true;f.house.stage="PLANNED";f.house.damaged.addAll(f.house.baseline.keySet());f.city.works.resources.put("minecraft:crafting_table",1);f.city.works.resources.put("minecraft:oak_planks",1);long money=f.money();CityWorks.worker(f.server,f.city,f.worker,0);h.assertTrue(f.house.stage.equals("BUILT")&&f.house.damaged.isEmpty()&&f.city.works.constructed==2&&f.money()==money,"Data artisan can construct an initial workshop using finite funds and materials");}h.succeed();}
 @GameTest(template="empty") public static void failedBusinessKeepsAssetsWhenOwnerSeeksWork(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var t=CityTrade.get(f.server);var b=new CityTrade.Business();b.id=UUID.randomUUID();b.worker=b.owner=f.worker;b.city=f.city.id;b.kind="baker";b.account="trade:"+b.id;b.site=f.bench.asLong();b.lastIncome=0;var town=new CityTrade.Town();town.city=f.city.id;town.urban=true;t.state.towns.put(town.city,town);b.stock[2].add(3,3000);t.state.businesses.put(b.id,b);d.state.enabled.add(f.city.id);CityEconomy.get(f.server).state.accounts.put(CityEconomy.person(f.worker),0L);long cash=f.money();t.exits(f.server,120000);h.assertTrue(b.closing&&b.stock[2].count==3&&b.stock[2].cents==3000&&f.person.role==RuralRules.Role.NONE&&f.money()==cash,"Exit changes employment, never erases or duplicates cargo/cash");t.state.businesses.remove(b.id);t.state.towns.remove(town.city);}h.succeed();}
 @GameTest(template="empty") public static void closedSuccessionDoesNotMintOrResurrect(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var t=CityTrade.get(f.server);var town=new CityTrade.Town();town.city=f.city.id;town.localOnly=true;t.state.towns.put(town.city,town);f.person.dead=true;var d=RuralSettlement.get(f.server);int n=d.state.people.size();long money=f.money();RuralSuccession.tick(f.server,f.city);f.city.works.clock=d.state.simulationTicks+72001;RuralSuccession.tick(f.server,f.city);h.assertTrue(d.state.people.size()==n&&f.money()==money&&f.person.dead,"Closed vacancies stay vacant without a local successor");t.state.towns.remove(town.city);}h.succeed();}
 @GameTest(template="empty") public static void employeeChangeDoesNotTransferPrivateBox(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var link=f.box();var box=NpcStorage.box(link);UUID owner=box.stock.family;box.stock.bread=6;var site=RuralSettlement.get(f.server).state.sites.values().stream().filter(v->f.worker.equals(v.worker)).findFirst().orElseThrow();site.worker=null;RuralTools.register(h.getLevel(),f.chest,link);h.assertTrue(owner.equals(box.stock.family)&&box.stock.bread==6,"Unemployment retains owner and goods");}h.succeed();}
 @GameTest(template="empty") public static void virtualCityDoesNotReadEmptyWorldAsDamage(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){f.city.works.virtual=true;h.getLevel().setBlock(f.bench,Blocks.AIR.defaultBlockState(),3);h.assertTrue(CityWorks.dataAt(f.server,f.city,f.bench.asLong()).is(Blocks.CRAFTING_TABLE),"Unprojected template remains authoritative");CityWorks.project(f.server,f.city);h.assertTrue(h.getLevel().getBlockState(f.bench).isAir(),"Data-only mode cannot overwrite the world");}h.succeed();}
 @GameTest(template="empty") public static void boundedMaterialSupplyKeepsExistingAssets(GameTestHelper h){var st=new CityHousing.State();CityHousing.seedCatalog(st);st.testSupply=true;var wood=st.market.get("minecraft:oak_planks");wood.stock=280;wood.cap=128;wood.supply=4;CityHousing.advanceSupply(st,1200);h.assertTrue(wood.stock==280&&wood.supplied==0,"Changing cap never deletes existing assets");wood.stock=126;CityHousing.advanceSupply(st,1200);h.assertTrue(wood.stock==128&&wood.supplied==2,"Only deficit to bounded cap is supplied and audited");h.succeed();}
 @GameTest(template="empty") public static void businessExitRequiresBothTimeAndFoodRisk(GameTestHelper h){h.assertTrue(!DataCityRules.exit(119999,0,0,4,0,5),"Five days wait required");h.assertTrue(!DataCityRules.exit(120000,0,20,4,0,5),"Safe family may keep stock");h.assertTrue(DataCityRules.exit(120000,0,0,4,0,5),"No income and food risk triggers exit");h.assertTrue(!DataCityRules.exit(120000,0,0,4,1000,5),"Real funds count, not nominal profit");h.succeed();}
 @GameTest(template="empty") public static void householdCookingNeedsRealWheatAndCredit(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var family=d.state.families.get(f.person.family);f.house.beds=1;f.house.residents.add(f.worker);var box=f.box();NpcStorage.box(box).stock.wheat=4;var t=CityTrade.get(f.server);var home=new FamilyLivelihood.Home();home.processor=f.worker;home.credit=2;t.state.households.put(family.id,home);long money=f.money();FamilyLivelihood.cook(f.server,family);h.assertTrue(NpcStorage.box(box).stock.wheat==2&&NpcStorage.box(box).stock.bread==2&&f.money()==money,"Time and actual wheat produce bread without silver creation");FamilyLivelihood.cook(f.server,family);h.assertTrue(NpcStorage.box(box).stock.bread==2,"Cannot spend the same work credit twice");t.state.households.remove(family.id);}h.succeed();}
 @GameTest(template="empty") public static void templateRejectsUnfundedBudgetWithoutPartialCreation(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var in=new CityDataTemplate.Template();in.min=new int[]{250000,90,250000};in.max=new int[]{250010,95,250010};in.budget=100;int n=CityData.get(f.server).cities.size();long money=f.money();boolean rejected=false;try{CityDataTemplate.create(f.server,f.worker,in);}catch(IllegalArgumentException ex){rejected=true;}h.assertTrue(rejected&&CityData.get(f.server).cities.size()==n&&f.money()==money,"Unfunded import has no partial mutation");}h.succeed();}
 @GameTest(template="empty") public static void pureDataTemplateCreatesNoActorsAndNoMoney(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var in=new CityDataTemplate.Template();in.min=new int[]{250000,90,250000};in.max=new int[]{250010,95,250010};in.source=f.city.id;in.budget=100;in.residents.add("数据居民");long money=f.money();var c=CityDataTemplate.create(f.server,f.worker,in);var d=RuralSettlement.get(f.server);UUID id=c.residents.iterator().next();h.assertTrue(c.works.virtual&&f.money()==money&&CityEconomy.get(f.server).balance(CityEconomy.person(id))==0&&h.getLevel().getEntity(id)==null,"Budget is transferred; zero-cash data person has no actor");CityTrade.get(f.server).state.towns.remove(c.id);d.state.people.remove(id);d.state.families.values().removeIf(v->v.city.equals(c.id));CityEconomy.get(f.server).state.accounts.remove(CityEconomy.person(id));CityEconomy.get(f.server).state.accounts.remove(CityEconomy.treasury(c.id));CityData.get(f.server).cities.remove(c.id);}h.succeed();}
}
